import java.util.*;

public class Solution {
    // Chave = letras ordenadas; LinkedHashMap preserva a ordem do primeiro de cada grupo. O(n·k log k).
    static List<List<String>> agrupar(List<String> palavras) {
        Map<String, List<String>> grupos = new LinkedHashMap<>();
        for (String p : palavras) {
            char[] letras = p.toCharArray();
            Arrays.sort(letras);
            grupos.computeIfAbsent(new String(letras), k -> new ArrayList<>()).add(p);
        }
        return new ArrayList<>(grupos.values());
    }
}

