import java.util.*;

public class Solution {
    // Min-heap de tamanho k ordenado do "pior" para o "melhor"; no fim, inverte. O(n log k).
    static List<Integer> topK(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) freq.merge(x, 1, Integer::sum);
        Comparator<Map.Entry<Integer, Integer>> pior = (a, b) -> {
            int c = Integer.compare(a.getValue(), b.getValue());
            return c != 0 ? c : Integer.compare(b.getKey(), a.getKey());
        };
        PriorityQueue<Map.Entry<Integer, Integer>> heap = new PriorityQueue<>(pior);
        for (var e : freq.entrySet()) {
            heap.offer(e);
            if (heap.size() > k) heap.poll();
        }
        List<Integer> out = new ArrayList<>();
        while (!heap.isEmpty()) out.add(heap.poll().getKey());
        Collections.reverse(out);
        return out;
    }
}

