import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void exemplo() {
        assertEquals(List.of(1, 2), Solution.topK(new int[]{1, 1, 1, 2, 2, 3}, 2));
    }

    @Test void empateMenorPrimeiro() {
        assertEquals(List.of(4, 7, 9), Solution.topK(new int[]{9, 7, 4, 4, 7, 9}, 3));
    }

    @Test void kMaiorQueDistintos() {
        assertEquals(List.of(5), Solution.topK(new int[]{5, 5}, 3));
    }

    @Test void grande() {
        int[] a = new int[200_000];
        for (int i = 0; i < a.length; i++) a[i] = i % 1000 == 0 ? 42 : i;
        assertEquals(42, Solution.topK(a, 1).get(0));
    }
}
